1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"io/fs"
10		"os"
11		"sync"
12		"sync/atomic"
13	)
14	
15	// node is one immutable version in a key's history. Versions form a linked
16	// list from newest to oldest; a snapshot pins the head current when it was
17	// acquired, so overwritten and deleted values stay readable through every
18	// view that references them.
19	type node struct {
20		value   []byte
21		present bool // false marks a delete; a present nil/empty value is still a hit
22		older   *node
23	}
24	
25	// view is an immutable map of keys to their newest version. Updates produce a
26	// fresh map; the current view and every snapshot simply point at one. Views
27	// are never mutated after publication, so reading them needs no lock. The
28	// maps share version chains with their successor views.
29	type view map[string]*node
30	
31	// Store is an open key-value store backed by a directory on disk.
32	type Store struct {
33		mu sync.Mutex // serializes writers and guards the fields below
34	
35		wal       *walWriter
36		current   atomic.Pointer[view] // latest committed view; lock-free for readers
37		snapshots atomic.Uint64        // cumulative number of snapshots handed out
38	
39		closed atomic.Bool
40	}
41	
42	// Snapshot is a stable read-only view of a store captured at one instant. It
43	// owns no store resources and stays usable after the store has been closed.
44	type Snapshot struct {
45		v atomic.Pointer[view] // nil once the snapshot is closed
46	}
47	
48	// Open opens or creates a persistent store in dir. A path that names a
49	// regular file rather than a directory returns an error wrapping
50	// fs.ErrInvalid.
51	func Open(dir string) (*Store, error) {
52		info, err := os.Stat(dir)
53		if err == nil {
54			if !info.IsDir() {
55				return nil, errNotDir
56			}
57		} else {
58			if !errors.Is(err, fs.ErrNotExist) {
59				return nil, err
60			}
61			if err := os.MkdirAll(dir, 0o700); err != nil {
62				return nil, err
63			}
64		}
65	
66		latest := make(view)
67		validSize, snapshotCount, err := replayWAL(dir, func(op byte, key string, value []byte) {
68			switch op {
69			case opPut:
70				latest[key] = &node{value: cloneBytes(value), present: true, older: latest[key]}
71			case opDelete:
72				latest[key] = &node{present: false, older: latest[key]}
73			}
74		})
75		if err != nil {
76			return nil, err
77		}
78	
79		wal, err := openWALWriter(dir, validSize)
80		if err != nil {
81			return nil, err
82		}
83	
84		s := &Store{wal: wal}
85		s.snapshots.Store(snapshotCount)
86		s.current.Store(&latest)
87		return s, nil
88	}
89	
90	// Put stores value under key. An empty key returns an error wrapping
91	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
92	// key reports a hit. The store does not keep a reference to value.
93	func (s *Store) Put(key string, value []byte) error {
94		s.mu.Lock()
95		defer s.mu.Unlock()
96		if s.closed.Load() {
97			return errStoreClosed
98		}
99		if key == "" {
100			return errEmptyKey
101		}
102		if err := s.wal.appendPut(key, value); err != nil {
103			return err
104		}
105		next := s.deriveView()
106		next[key] = &node{value: cloneBytes(value), present: true, older: (*s.current.Load())[key]}
107		s.current.Store(&next)
108		return nil
109	}
110	
111	// Get returns the latest committed value for key. Empty keys, keys never
112	// written and deleted keys are all misses: ok is false and err is nil. The
113	// returned bytes are owned by the caller.
114	func (s *Store) Get(key string) ([]byte, bool, error) {
115		if s.closed.Load() {
116			return nil, false, errStoreClosed
117		}
118		if key == "" {
119			return nil, false, nil
120		}
121		val, ok := lookup(*s.current.Load(), key)
122		return val, ok, nil
123	}
124	
125	// Delete removes key. Deleting an empty key returns an error wrapping
126	// fs.ErrInvalid; deleting a key that was never written or is already deleted
127	// is not an error and commits nothing.
128	func (s *Store) Delete(key string) error {
129		s.mu.Lock()
130		defer s.mu.Unlock()
131		if s.closed.Load() {
132			return errStoreClosed
133		}
134		if key == "" {
135			return errEmptyKey
136		}
137		cur := *s.current.Load()
138		if n := cur[key]; n == nil || !n.present {
139			return nil // nothing live to delete: idempotent no-op
140		}
141		if err := s.wal.appendDelete(key); err != nil {
142			return err
143		}
144		next := s.deriveView()
145		next[key] = &node{present: false, older: cur[key]}
146		s.current.Store(&next)
147		return nil
148	}
149	
150	// deriveView returns a shallow, mutable copy of the current view. Callers
151	// must hold s.mu and publish the result through s.current before unlocking.
152	func (s *Store) deriveView() view {
153		cur := *s.current.Load()
154		next := make(view, len(cur)+1)
155		for k, v := range cur {
156			next[k] = v
157		}
158		return next
159	}
160	
161	// Snapshot acquires a stable view. It never observes writes committed after
162	// it returns, and keeps serving that view regardless of later writes,
163	// deletes or Store.Close, until the Snapshot itself is closed.
164	func (s *Store) Snapshot() (*Snapshot, error) {
165		s.mu.Lock()
166		defer s.mu.Unlock()
167		if s.closed.Load() {
168			return nil, errStoreClosed
169		}
170		count := s.snapshots.Add(1)
171		if err := s.wal.appendMeta(count); err != nil {
172			s.snapshots.Add(^uint64(0))
173			return nil, err
174		}
175		snap := &Snapshot{}
176		snap.v.Store(s.current.Load())
177		return snap, nil
178	}
179	
180	// Get reads key from the snapshot's fixed view. Old values overwritten or
181	// deleted afterwards are still readable; keys created afterwards, empty
182	// keys and keys absent or deleted when the snapshot was taken are misses. A
183	// read from a closed snapshot is also a plain miss, never an error. The
184	// returned bytes are owned by the caller.
185	func (s *Snapshot) Get(key string) ([]byte, bool) {
186		if key == "" {
187			return nil, false
188		}
189		v := s.v.Load()
190		if v == nil {
191			return nil, false // closed snapshot
192		}
193		n := (*v)[key]
194		if n == nil || !n.present {
195			return nil, false
196		}
197		return cloneBytes(n.value), true
198	}
199	
200	// Close releases the snapshot's fixed view. Closing more than once is a
201	// no-op returning nil.
202	func (s *Snapshot) Close() error {
203		s.v.Store(nil)
204		return nil
205	}
206	
207	// Close flushes and closes the store. Data already committed stays complete
208	// and readable after reopening the directory. Snapshots still open keep
209	// serving their fixed views until closed themselves; closing an already
210	// closed store is a no-op returning nil.
211	func (s *Store) Close() error {
212		s.mu.Lock()
213		if !s.closed.CompareAndSwap(false, true) {
214			s.mu.Unlock()
215			return nil
216		}
217		wal := s.wal
218		s.wal = nil
219		s.mu.Unlock()
220	
221		return wal.close()
222	}
223	
224	func lookup(v view, key string) ([]byte, bool) {
225		n := v[key]
226		if n == nil || !n.present {
227			return nil, false
228		}
229		return cloneBytes(n.value), true
230	}
231	
232	func cloneBytes(b []byte) []byte {
233		if b == nil {
234			return nil
235		}
236		c := make([]byte, len(b))
237		copy(c, b)
238		return c
239	}
