1	package snapshot
2	
3	// Stats describes the current state of a store.
4	type Stats struct {
5		// Keys is the number of live keys (present values) in the latest view.
6		Keys int
7		// Snapshots is the cumulative number of snapshots successfully handed
8		// out by this store across all openings of the same directory.
9		Snapshots uint64
10		// AvgBytes is the mean length of live values, rounded half-up to two
11		// decimal places. It is 0 when there are no live keys.
12		AvgBytes float64
13	}
14	
15	// Stats returns statistics over the latest committed view. It does not count
16	// as taking a snapshot.
17	func (s *Store) Stats() Stats {
18		v := *s.current.Load()
19		var keys int
20		var totalBytes int
21		for _, n := range v {
22			if n.present {
23				keys++
24				totalBytes += len(n.value)
25			}
26		}
27		st := Stats{Keys: keys, Snapshots: s.snapshots.Load()}
28		if keys > 0 {
29			// Exact half-up rounding to hundredths using integer math, avoiding
30			// any floating-point tie or negative-zero issues.
31			scaled := totalBytes * 100
32			hundredths, rem := scaled/keys, scaled%keys
33			if 2*rem >= keys {
34				hundredths++
35			}
36			st.AvgBytes = float64(hundredths) / 100
37		}
38		return st
39	}
40

