436	func TestConcurrentIsolation(t *testing.T) {
437		s := openStore(t, tempDir(t))
438	
439		const writers = 4
440		const iterations = 200
441	
442		var writersWg sync.WaitGroup
443		for w := 0; w < writers; w++ {
444			writersWg.Add(1)
445			go func(w int) {
446				defer writersWg.Done()
447				key := fmt.Sprintf("k%d", w)
448				for i := 0; i < iterations; i++ {
449					v := bytes.Repeat([]byte{byte('a' + w)}, i+1)
450					if err := s.Put(key, v); err != nil {
451						t.Errorf("put: %v", err)
452						return
453					}
454				}
455			}(w)
456		}
457	
458		stop := make(chan struct{})
459		var readersWg sync.WaitGroup
460		readersWg.Add(1)
461		go func() {
462			defer readersWg.Done()
463			for {
464				select {
465				case <-stop:
466					return
467				default:
468				}
469				snap, err := s.Snapshot()
470				if err != nil {
471					t.Errorf("snapshot: %v", err)
472					return
473				}
474				for w := 0; w < writers; w++ {
475					key := fmt.Sprintf("k%d", w)
476					v, ok := snap.Get(key)
477					if !ok {
478						continue // key may not have been written yet
479					}
480					// Every committed value is a whole, un-torn run of one byte.
481					if !allByte(v, byte('a'+w)) {
482						t.Errorf("torn/aliased value for %s: %q", key, v)
483					}
484					// The fixed view never changes between reads of one snapshot.
485					v2, ok := snap.Get(key)
486					if !ok || !bytes.Equal(v, v2) {
487						t.Errorf("snapshot view changed between reads")
488					}
489				}
490				snap.Close()
491			}
492		}()
493	
494		writersWg.Wait()
495		close(stop)
496		readersWg.Wait()
497	}
