614		if err := s.Close(); err != nil {
615			t.Fatal(err)
616		}
617		readerWg.Wait()
618	
619		if sawClosed.Load() == 0 {
620			t.Fatal("no reader observed fs.ErrClosed after close")
621		}
622	
623		// Snapshots already handed out survive close; verify one explicitly.
624		// (Acquire-then-close ordering.)
625		s2 := openStore(t, tempDir(t))
626		if err := s2.Put("k", []byte("v")); err != nil {
627			t.Fatal(err)
628		}
629		snap, err := s2.Snapshot()
630		if err != nil {
631			t.Fatal(err)
632		}
633		if err := s2.Put("k", []byte("v2")); err != nil {
634			t.Fatal(err)
635		}
636		if err := s2.Close(); err != nil {
637			t.Fatal(err)
638		}
639		if got, ok := snap.Get("k"); !ok || string(got) != "v" {
640			t.Fatalf("snapshot broken by concurrent close: %q %v", got, ok)
641		}
642		if err := snap.Close(); err != nil {
