1	// Command snapshotctl inspects snapshot-kv stores.
2	//
3	// Usage:
4	//
5	//	snapshotctl --dir <path> stats
6	//
7	// stats prints one compact JSON line, terminated by a newline:
8	//
9	//	{"keys":3,"snapshots":2,"avgBytes":4.67}
10	package main
11	
12	import (
13		"fmt"
14		"io"
15		"os"
16	
17		"github.com/Hulalalalalalalalalalala/snapshot-kv"
18	)
19	
20	func main() {
21		os.Exit(run(os.Args[1:], os.Stdout))
22	}
23	
24	func run(args []string, stdout io.Writer) int {
25		dir, cmd, ok := parseArgs(args)
26		if !ok || cmd != "stats" {
27			return 1
28		}
29	
30		// stats inspects an existing store: a missing path or a non-directory
31		// cannot be opened, so exit 1 silently instead of creating anything.
32		if info, err := os.Stat(dir); err != nil || !info.IsDir() {
33			return 1
34		}
35	
36		store, err := snapshot.Open(dir)
37		if err != nil {
38			return 1
39		}
40		defer store.Close()
41	
42		st := store.Stats()
43		// Fixed key order keys, snapshots, avgBytes; no spaces after colons or
44		// commas. %.2f always emits exactly two decimals and never "-0" for the
45		// non-negative values Stats produces.
46		_, err = fmt.Fprintf(stdout, "{\"keys\":%d,\"snapshots\":%d,\"avgBytes\":%.2f}\n",
47			st.Keys, st.Snapshots, st.AvgBytes)
48		if err != nil {
49			return 1
50		}
51		return 0
52	}
53	
54	// parseArgs accepts "--dir <path> stats" (or "--dir=<path>").
