	if !strings.HasSuffix(line, "}\n") || strings.Count(line, "\n") != 1 {
		t.Fatalf("not exactly one line: %q", line)
	}
	if strings.ContainsAny(line, " ") {
		t.Fatalf("contains spaces: %q", line)
	}
}

